-- Modulo 66 Planillas: planilla mensual y complementaria con su calculo por empleado y boletas.
-- Spec: docs/specs/modulo66-planillas-backend.md (4).
-- Anade ademas la clave foranea que faltaba en DescuentosCuotaPrestamo.PlanillaId (modulo 67).

CREATE TABLE "ParametrosPlanilla" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Clave" character varying(50) NOT NULL,
    "Valor" numeric(14,4) NOT NULL,
    "Descripcion" character varying(200) NOT NULL,
    CONSTRAINT "PK_ParametrosPlanilla" PRIMARY KEY ("Id")
);
CREATE UNIQUE INDEX "IX_ParametrosPlanilla_Clave" ON "ParametrosPlanilla" ("Clave");

CREATE TABLE "ParametrosPension" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Codigo" character varying(20) NOT NULL,
    "Sistema" character varying(10) NOT NULL,
    "TasaAporte" numeric(6,4) NOT NULL,
    "TasaPrimaSeguro" numeric(6,4) NOT NULL,
    "TasaComision" numeric(6,4) NOT NULL,
    "RemuneracionMaximaAsegurable" numeric(12,2),
    CONSTRAINT "PK_ParametrosPension" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_ParametrosPension_Sistema" CHECK ("Sistema" IN ('ONP', 'AFP'))
);
CREATE UNIQUE INDEX "IX_ParametrosPension_Codigo" ON "ParametrosPension" ("Codigo");

CREATE TABLE "TramosQuintaCategoria" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Orden" integer NOT NULL,
    "HastaUit" numeric(8,2),
    "Tasa" numeric(6,4) NOT NULL,
    CONSTRAINT "PK_TramosQuintaCategoria" PRIMARY KEY ("Id")
);
CREATE UNIQUE INDEX "IX_TramosQuintaCategoria_Orden" ON "TramosQuintaCategoria" ("Orden");

CREATE TABLE "AfiliacionesPension" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "EmpleadoId" integer NOT NULL,
    "ParametroPensionId" integer NOT NULL,
    "Cuspp" character varying(12),
    "FechaAfiliacion" date NOT NULL,
    CONSTRAINT "PK_AfiliacionesPension" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AfiliacionesPension_Empleados_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_AfiliacionesPension_ParametrosPension_ParametroPensionId" FOREIGN KEY ("ParametroPensionId") REFERENCES "ParametrosPension" ("Id") ON DELETE RESTRICT
);
CREATE UNIQUE INDEX "IX_AfiliacionesPension_EmpleadoId" ON "AfiliacionesPension" ("EmpleadoId");
CREATE INDEX "IX_AfiliacionesPension_ParametroPensionId" ON "AfiliacionesPension" ("ParametroPensionId");

CREATE TABLE "Planillas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Numero" character varying(20) NOT NULL,
    "Anio" integer NOT NULL,
    "Mes" integer NOT NULL,
    "Tipo" character varying(20) NOT NULL,
    "Estado" character varying(20) NOT NULL,
    "Empleados" integer NOT NULL DEFAULT 0,
    "Incidencias" integer NOT NULL DEFAULT 0,
    "TotalIngresos" numeric(12,2) NOT NULL DEFAULT 0,
    "TotalDescuentos" numeric(12,2) NOT NULL DEFAULT 0,
    "TotalNeto" numeric(12,2) NOT NULL DEFAULT 0,
    "TotalAportesEmpleador" numeric(12,2) NOT NULL DEFAULT 0,
    "FechaCalculo" timestamp with time zone,
    "CalculadoPor" character varying(100),
    "AprobadoPor" character varying(100),
    "FechaAprobacion" timestamp with time zone,
    "FechaPago" date,
    CONSTRAINT "PK_Planillas" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Planillas_Tipo" CHECK ("Tipo" IN ('Mensual', 'Complementaria')),
    CONSTRAINT "CK_Planillas_Estado" CHECK ("Estado" IN ('Borrador', 'Calculada', 'Aprobada', 'Pagada')),
    CONSTRAINT "CK_Planillas_Mes" CHECK ("Mes" BETWEEN 1 AND 12)
);
CREATE UNIQUE INDEX "IX_Planillas_Numero" ON "Planillas" ("Numero");
CREATE UNIQUE INDEX "IX_Planillas_Anio_Mes_Tipo" ON "Planillas" ("Anio", "Mes", "Tipo");

CREATE TABLE "PlanillaDetalles" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "PlanillaId" integer NOT NULL,
    "EmpleadoId" integer NOT NULL,
    "ContratoLaboralId" integer,
    "Cargo" character varying(100) NOT NULL,
    "SueldoBasico" numeric(12,2) NOT NULL,
    "DiasContrato" integer NOT NULL,
    "DiasSinGoce" integer NOT NULL,
    "DiasFalta" integer NOT NULL,
    "DiasLaborados" integer NOT NULL,
    "IngresoBasico" numeric(12,2) NOT NULL,
    "MinutosExtra" integer NOT NULL,
    "IngresoHorasExtra" numeric(12,2) NOT NULL,
    "IngresoBonos" numeric(12,2) NOT NULL,
    "TotalIngresos" numeric(12,2) NOT NULL,
    "CodigoPension" character varying(20),
    "DescuentoPension" numeric(12,2) NOT NULL,
    "DescuentoQuinta" numeric(12,2) NOT NULL,
    "DescuentoPrestamos" numeric(12,2) NOT NULL,
    "TotalDescuentos" numeric(12,2) NOT NULL,
    "Neto" numeric(12,2) NOT NULL,
    "AporteEssalud" numeric(12,2) NOT NULL,
    "Incidencia" character varying(300),
    "NumeroBoleta" character varying(30),
    CONSTRAINT "PK_PlanillaDetalles" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PlanillaDetalles_Planillas_PlanillaId" FOREIGN KEY ("PlanillaId") REFERENCES "Planillas" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_PlanillaDetalles_Empleados_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_PlanillaDetalles_ContratosLaborales_ContratoLaboralId" FOREIGN KEY ("ContratoLaboralId") REFERENCES "ContratosLaborales" ("Id") ON DELETE RESTRICT
);
CREATE UNIQUE INDEX "IX_PlanillaDetalles_PlanillaId_EmpleadoId" ON "PlanillaDetalles" ("PlanillaId", "EmpleadoId");
CREATE INDEX "IX_PlanillaDetalles_EmpleadoId" ON "PlanillaDetalles" ("EmpleadoId");
CREATE INDEX "IX_PlanillaDetalles_ContratoLaboralId" ON "PlanillaDetalles" ("ContratoLaboralId");
CREATE UNIQUE INDEX "IX_PlanillaDetalles_NumeroBoleta" ON "PlanillaDetalles" ("NumeroBoleta");

CREATE TABLE "BonosPlanilla" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "EmpleadoId" integer NOT NULL,
    "Anio" integer NOT NULL,
    "Mes" integer NOT NULL,
    "TipoPlanilla" character varying(20) NOT NULL,
    "Concepto" character varying(100) NOT NULL,
    "Monto" numeric(12,2) NOT NULL,
    "PlanillaId" integer,
    CONSTRAINT "PK_BonosPlanilla" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_BonosPlanilla_Empleados_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_BonosPlanilla_Planillas_PlanillaId" FOREIGN KEY ("PlanillaId") REFERENCES "Planillas" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_BonosPlanilla_TipoPlanilla" CHECK ("TipoPlanilla" IN ('Mensual', 'Complementaria')),
    CONSTRAINT "CK_BonosPlanilla_Mes" CHECK ("Mes" BETWEEN 1 AND 12),
    CONSTRAINT "CK_BonosPlanilla_Monto" CHECK ("Monto" > 0)
);
CREATE INDEX "IX_BonosPlanilla_EmpleadoId" ON "BonosPlanilla" ("EmpleadoId");
CREATE INDEX "IX_BonosPlanilla_PlanillaId" ON "BonosPlanilla" ("PlanillaId");
CREATE INDEX "IX_BonosPlanilla_Anio_Mes" ON "BonosPlanilla" ("Anio", "Mes");

ALTER TABLE "DescuentosCuotaPrestamo" ADD CONSTRAINT "FK_DescuentosCuotaPrestamo_Planillas_PlanillaId" FOREIGN KEY ("PlanillaId") REFERENCES "Planillas" ("Id") ON DELETE RESTRICT;
